let learning=Learning.empty(),learningLoadError=false,zoneFilter='',posFilter='',cardRevealed=false;
try{const raw=localStorage.getItem(Learning.key);if(raw)learning=Learning.validate(JSON.parse(raw));}catch{learningLoadError=true;}
function persistLearning(next){if(learningLoadError){toast('30日学習の保存データを読み込めません。設定からデータを退避・復元してください。');return false;}try{localStorage.setItem(Learning.key,JSON.stringify(next));learning=next;return true;}catch{toast('保存できません。空き容量を確認してください。進捗は進めていません。');return false;}}
function changeLearning(fn){const next=JSON.parse(JSON.stringify(learning));fn(next);if(!persistLearning(next))return false;cardRevealed=false;return true;}
function wordNumber(w){return w.course==='core'?String(w.rank).padStart(3,'0'):w.id.slice(-3);}
function courseWords(){return WORDS.filter(w=>learning.course==='core'?w.course==='core':w.course!=='core');}
function matchesCoreFilters(w){return w.course!=='core'||(!zoneFilter||w.zone===Number(zoneFilter))&&(!posFilter||w.part_of_speech===posFilter);}
const oldDictionary=dictionary;
dictionary=function(){let html=oldDictionary();html=html.replace(/<footer>[\s\S]*?<\/footer>$/,learning.course==='core'?'<footer>基礎フランス語1000語 · v1.1 編集・QA版<br>外部辞書との全件照合は未完了。頻度順位・CEFRは未検証のため表示しません。</footer>':'<footer>思想・哲学100語：ラカン20語 ＋ フーコー80語<br>原語をタップすると説明・お気に入りを表示します。訳語・解説は読解用草稿です。</footer>');if(learning.course==='core')html=html.replace('<div id="results">',`<div class="core-filters"><label>Zone<select id="zone-filter"><option value="">全1000語</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${zoneFilter==n?'selected':''}>Zone ${n}（${(n-1)*200+1}〜${n*200}）</option>`).join('')}</select></label><label>品詞<select id="pos-filter"><option value="">すべての品詞</option>${Object.entries(POS_LABELS).map(([k,v])=>`<option value="${k}" ${posFilter===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div id="results">`);return html;};
const oldDetail=detail;
detail=function(id){const w=WORDS.find(w=>w.id===id);if(w?.course!=='core')return oldDetail(id);return `<div class="detail-top"><a class="back" href="#dictionary">← 単語帳</a>${favBtn(w)}</div><p class="eyebrow">No. ${wordNumber(w)} · Zone ${w.zone}</p><h1 class="term-heading"><span class="fr" lang="fr">${esc(w.termFr)}</span>${audioBtn(w)}</h1>${wordTags(w)}<p><button class="primary" data-answer="detail-answer" aria-expanded="false" aria-controls="detail-answer">答えを見る</button></p><section id="detail-answer" hidden><div class="meaning-block">${meaningHtml(w)}</div></section><footer>${esc(w.reviewStatus)}<br>学習順：${w.rank} / マスターID：${esc(w.sourceId)}</footer>`;};
function wordTags(w){return `<div class="word-tags"><span class="pos-label">${esc(POS_LABELS[w.part_of_speech]||w.part_of_speech||'')}</span>${w.gender?`<span class="notes">性：${esc(w.gender)}</span>`:''}</div>`;}
function plannedDate(d){if(!learning.startDate)return '';const date=new Date(learning.startDate+'T00:00:00Z');date.setUTCDate(date.getUTCDate()+d-1);return date.toISOString().slice(0,10);}
function studyHome(){const d=learning.currentDay,st=Learning.stats(learning.days[d]),schedule=Learning.scheduled(learning);const planned=schedule===null?'開始日を登録してください':schedule<1?'開始予定日前です':schedule>30?'開始日から30日を過ぎています。残りの学習を続けられます。':`日付上の予定：Day ${schedule} / Zone ${Learning.dayZone(schedule)}`;return `<div class="eyebrow">30 DAYS · 基礎1000語</div><h1>30日集中学習</h1><p class="notes">200語 × 5日 × 6周。覚えた語も毎周確認します。</p><div class="plan-controls"><label>学習開始日<input type="date" id="start-date" value="${learning.startDate||Learning.localDate()}"></label><button id="save-start">${learning.startDate?'開始日を変更':'開始日を登録'}</button></div><p class="notes">${planned}<br>予定日と進捗は別に保存します。開始日を変えても履歴は残ります。</p><div class="study-dashboard"><div class="detail-top"><strong>Day ${d} / 30</strong><span>${Learning.round(d)}周目</span></div><h2>今日のZone ${Learning.dayZone(d)}</h2><p>${st.done} / 200語 ${st.complete?'· 完了':''}</p><div class="progress"><div style="width:${st.done/2}%"></div></div><p>習得率 ${st.rate}% <small class="notes">（判定済み${st.done}語中「覚えた」${st.known}語）</small></p><button class="primary" id="begin-day" ${!learning.startDate?'disabled':''}>${st.complete?'このDayを確認する':st.done?'今日の学習を再開':'今日の学習を開始'}</button></div><label>学習日を選択<select id="day-select">${Array.from({length:30},(_,i)=>i+1).map(n=>`<option value="${n}" ${n===d?'selected':''}>Day ${n} · ${Learning.round(n)}周目 · Zone ${Learning.dayZone(n)}${Learning.stats(learning.days[n]).complete?' ✓':''}</option>`).join('')}</select></label><h2>30日間の記録</h2><div class="day-grid">${Array.from({length:30},(_,i)=>i+1).map(n=>{const t=Learning.stats(learning.days[n]);return `<button data-day="${n}" class="${n===d?'day-active':''} ${t.complete?'day-complete':''}" aria-label="Day ${n} ${t.done}/200語${t.complete?' 完了':''}"><strong>Day ${n}</strong><small>${plannedDate(n).slice(5)||'Zone '+Learning.dayZone(n)}</small><small>${t.done}/200 ${t.complete?'✓':''}</small></button>`;}).join('')}</div><h2>周回別の結果</h2><div class="round-list">${Array.from({length:6},(_,r)=>{const stats=Array.from({length:5},(_,z)=>Learning.stats(learning.days[r*5+z+1]));return `<p>${r+1}周目 <span>${stats.reduce((n,s)=>n+s.done,0)} / 1000語 · 覚えた ${stats.reduce((n,s)=>n+s.known,0)}語</span></p>`;}).join('')}</div>`;}
function studyCard(){const d=learning.currentDay,day=learning.days[d];if(!day)return '<p>開始日と学習日を選んでください。</p><a href="#study">30日学習へ</a>';const st=Learning.stats(day),index=day.position;if(index>=day.wordIds.length)return `<div class="eyebrow">DAY ${d} · ${Learning.round(d)}周目</div><h1>${st.complete?'200語を確認しました':'このDayの末尾です'}</h1><p>${st.done}/200語 · 覚えた ${st.known}語 · 習得率 ${st.rate}%</p>${!st.complete?'<button id="resume-unanswered" class="primary">未判定の単語へ</button>':''}<div class="actions"><button data-move="-1">前の単語</button>${d<30?'<button id="next-day" class="primary">次のDayへ</button>':''}</div><p><a href="#study">進捗を見る</a></p>`;const w=CORE_WORDS.find(w=>w.id===day.wordIds[index]);if(!w)return '<p>この単語は現在の教材にありません。履歴は保持しています。</p><a href="#study">進捗へ戻る</a>';return flashCard(w,index,200,`Day ${d} / 30 · ${Learning.round(d)}周目 · Zone ${Learning.dayZone(d)}`,st.done,'main');}
function flashCard(w,index,total,title,done,mode){return `<div class="detail-top"><a class="back" href="${mode==='main'?'#study':'#review'}">← 進捗へ</a><span class="notes">${esc(title)}</span></div><p class="notes">${index+1} / ${total}語 · ${mode==='main'?'判定済み':'確認済み'} ${done}語</p><div class="progress"><div style="width:${done/total*100}%"></div></div><div class="card memory-card"><div class="detail-top"><span class="eyebrow">No. ${wordNumber(w)}</span>${favBtn(w)}</div><div class="fr" lang="fr">${esc(w.termFr)}</div>${wordTags(w)}${audioBtn(w)}${cardRevealed?`<div class="answer"><div class="meaning-block">${esc(w.termJa)}</div></div>`:'<button class="primary" id="show-meaning">意味を表示</button>'}</div><div class="actions"><button data-judge="no" ${cardRevealed?'':'disabled'}>覚えていない</button><button class="primary" data-judge="yes" ${cardRevealed?'':'disabled'}>覚えた</button></div><div class="actions word-navigation"><button data-move="-1" ${index===0?'disabled':''}>← 前の単語</button><button data-move="1">次の単語 →</button></div><p class="notes">判定すると自動で次へ進みます。「次の単語」だけでは判定済みになりません。</p>`;}
function reviewScreen(){if(learning.course==='thought')return review();const weak=CORE_WORDS.filter(w=>learning.weak[w.id]);const ws=learning.weakSession;return `<div class="eyebrow">RÉVISION · 基礎1000語</div><h1>苦手単語の復習</h1><p>覚えていない単語：${weak.length}語</p><p class="notes">直近の判定で「覚えていない」とした語です。ここでの復習は30日学習の過去の記録を変更しません。</p>${ws&&ws.position<ws.ids.length?`<p><a class="button-link" href="#weak">途中の復習を再開（${ws.position}/${ws.ids.length}語）</a></p>`:''}<button id="start-weak" class="primary" ${weak.length?'':'disabled'}>苦手単語を${ws?'新しく':''}復習する</button><p class="notes">思想・哲学100語の復習は、上部の教材切り替えから利用できます。</p>`;}
function weakCard(){const ws=learning.weakSession;if(!ws)return '<p>復習する単語を選んでください。</p><a href="#review">復習へ</a>';if(ws.position>=ws.ids.length)return '<h1>復習が終わりました</h1><p>30日学習の履歴はそのまま残っています。</p><a href="#review">苦手単語の一覧へ</a>';const w=CORE_WORDS.find(w=>w.id===ws.ids[ws.position]);if(!w)return '<p>この単語は現在の教材にありません。履歴は保持しています。</p><a href="#review">復習へ戻る</a>';return flashCard(w,ws.position,ws.ids.length,'苦手単語',ws.position,'weak');}
function bindV13(){
 if(!$('#course')){const label=document.createElement('label');label.className='course-switch';label.innerHTML='<span>教材</span><select id="course"><option value="core">基礎フランス語1000語</option><option value="thought">思想・哲学100語</option></select>';document.querySelector('header').append(label);}
 $('#course').value=learning.course;$('#course').onchange=e=>{if(!changeLearning(s=>s.course=e.target.value)){e.target.value=learning.course;return;}q='';favorites=false;session=null;listScroll=0;location.hash='#dictionary';render();};
 if($('#zone-filter'))$('#zone-filter').onchange=e=>{zoneFilter=e.target.value;renderList();};if($('#pos-filter'))$('#pos-filter').onchange=e=>{posFilter=e.target.value;renderList();};
 if($('#day-select'))$('#day-select').onchange=e=>{if(changeLearning(s=>s.currentDay=Number(e.target.value)))render();};
 if($('#file'))$('#file').onchange=importAll;
}
function goDay(n,open=false){if(changeLearning(s=>{s.currentDay=n;s.course='core';Learning.ensureDay(s,n,CORE_WORDS);})){location.hash=open?'#learn':'#study';render();}}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.id==='export'){e.stopImmediatePropagation();exportAll();return;}
 if(b.id==='save-start'){const date=$('#start-date').value;if(!Learning.validDate(date)){toast('開始日を入力してください');return;}if(changeLearning(s=>s.startDate=date))render();}
 if(b.dataset.day)goDay(Number(b.dataset.day));
 if(b.id==='begin-day')goDay(learning.currentDay,true);
 if(b.id==='next-day')goDay(learning.currentDay+1,true);
 if(b.id==='resume-unanswered'){if(changeLearning(s=>{const day=s.days[s.currentDay];day.position=day.wordIds.findIndex(id=>!day.results[id]?.length);}))render();}
 if(b.id==='show-meaning'){cardRevealed=true;render();}
 if(b.dataset.move){const delta=Number(b.dataset.move);if(changeLearning(s=>{if(location.hash==='#weak'){const ws=s.weakSession;ws.position=Math.max(0,Math.min(ws.ids.length,ws.position+delta));}else{const day=s.days[s.currentDay];day.position=Math.max(0,Math.min(200,day.position+delta));}}))render();}
 if(b.dataset.judge&&cardRevealed){if(changeLearning(s=>{if(location.hash==='#weak'){const ws=s.weakSession;Learning.judgeWeak(s,ws.ids[ws.position],b.dataset.judge==='yes');}else{const day=s.days[s.currentDay];Learning.judge(s,s.currentDay,day.wordIds[day.position],b.dataset.judge==='yes',CORE_WORDS);}}))render();}
 if(b.id==='start-weak'){if(changeLearning(s=>s.weakSession={ids:CORE_WORDS.filter(w=>s.weak[w.id]).map(w=>w.id),position:0})){location.hash='#weak';render();}}
},true);
function downloadBackup(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportAll(){if(learningLoadError||storageError){downloadBackup({rawLegacy:localStorage.getItem(KEY),rawLearning:localStorage.getItem(Learning.key)},'lexique-recovery-raw.json');toast('読み込めないデータを含む原本を退避しました。通常の復元用ファイルではありません。');return;}downloadBackup({version:3,exportedAt:new Date().toISOString(),masterVersion:CORE_MASTER.version,customWords:state.customWords,records:state.records,settings:state.settings,learning},'lexique-backup-'+Learning.localDate()+'.json');}
async function importAll(e){const f=e.target.files[0];if(!f)return;try{
 if(f.size>25000000)throw Error('ファイルは25MBまでです');const x=JSON.parse(await f.text());if(![1,2,3].includes(x.version))throw Error('対応しない形式です');const custom=x.version===1?state.customWords:validateCustom(x.customWords);const all=[...BUILTIN_WORDS,...custom.map(materialize)];const records=validate({...x,version:2},all);const next={...state,customWords:custom,records:x.version<3?{...Object.fromEntries(Object.entries(state.records).filter(([id])=>id.startsWith('core:'))),...records}:records};if(x.settings){if(!Number.isFinite(x.settings.rate)||x.settings.rate<.6||x.settings.rate>1.2||typeof x.settings.voice!=='string')throw Error('音声設定が不正です');next.settings=x.settings;}
 const nextLearning=x.version===3?Learning.validate(x.learning):learning;
 if(!confirm(x.version===3?'お気に入り・学習記録・30日学習の進捗をバックアップの内容で置き換えます。よろしいですか？':'旧形式の記録を読み込みます。現在の30日学習の進捗は保持します。よろしいですか？'))return;
 const old=localStorage.getItem(KEY),oldLearning=localStorage.getItem(Learning.key);
 try{localStorage.setItem(KEY,JSON.stringify(next));if(x.version===3)localStorage.setItem(Learning.key,JSON.stringify(nextLearning));}catch(err){try{old===null?localStorage.removeItem(KEY):localStorage.setItem(KEY,old);oldLearning===null?localStorage.removeItem(Learning.key):localStorage.setItem(Learning.key,oldLearning);}catch{}throw Error('保存できませんでした。バックアップを保持して空き容量を確認してください。');}
 state=next;learning=nextLearning;storageError=false;if(x.version===3)learningLoadError=false;WORDS.splice(0,WORDS.length,...all);session=null;cardRevealed=false;render();toast('バックアップを復元しました');
 }catch(err){toast('読み込めません：'+err.message);}finally{if($('#file'))$('#file').value='';}}
window.addEventListener('hashchange',()=>{cardRevealed=false;render();});
render();if(learningLoadError)toast('30日学習の保存データを読み込めません。原本は保持しています。設定から退避してください。');
